                Span::styled("enter", key),
                Span::styled(" confirms · ", muted),
                Span::styled("←→", key),
                Span::styled(" back · ", muted),
                Span::styled("esc", key),
                Span::styled(" denies", muted),
            ]
        },
        None => if narrow {
            vec![Span::styled("y", key), Span::styled("/", muted), Span::styled("n", key), Span::styled(" or ", muted), Span::styled("←→ enter", key), Span::styled(" · ", muted), Span::styled("esc", key), Span::styled(" denies", muted)]
        } else {
            vec![
                Span::styled("y", key),
                Span::styled(" approve · ", muted),
                Span::styled("n", key),
                Span::styled(" deny · ", muted),
                Span::styled("←→", key),
                Span::styled("/", muted),
                Span::styled("tab", key),
                Span::styled(" move, ", muted),
                Span::styled("enter", key),
                Span::styled(" takes ▸ · ", muted),
                Span::styled("↑↓", key),
                Span::styled(" scroll · ", muted),
                Span::styled("esc", key),
                Span::styled(" denies", muted),
            ]
        },
    };
    let lines: Vec<Line> = match &approval.patch {
        Some(patch) => {
            let geo = Geometry { width, indent: 1, num_width: diff_view::patch_num_width(patch) };
            diff_view::panel_rows(patch)
                .into_iter()
                .filter(|row| !matches!(row, diff_view::Row::File(_) | diff_view::Row::Blank))
                .flat_map(|row| diff_view::panel_row_lines(patch, row, geo, Fit::Wrap, &pal))
                .collect()
        }
        // Text rows (commands, scripts, arguments) wrap to the panel so no part of a line is cut off at its edge.
        None => approval
            .lines
            .iter()
            .flat_map(|line| markdown::wrap(vec![Span::styled(line.text.clone(), line_style(line.kind))], width, Vec::new(), vec![Span::raw("    ")]))
            .collect(),
    };
    // The panel fits its content (heading, the change, decisions) and never needs more than the area; the hint row
    // is the first thing dropped when space is short, then the gap rows.
    let available = usize::from(area.height.saturating_sub(2));
    let fixed = head.len() + footer.len();
    // The hint or notice never takes a row the text needs: text that must be folded needs two body rows (one row and
    // the fold marker), so on a short terminal a refusal's notice is left out and the marker explains the refusal.
    let body_min = if lines.len() > 1 { 2 } else { usize::from(!lines.is_empty()) };
    let with_hint = available >= fixed + 1 + 2 + body_min;
    if with_hint {
        footer.push(Line::from(hint));
    }
    let gaps = usize::from(available >= head.len() + footer.len() + 2 + lines.len().min(1));
    let body_room = available.saturating_sub(head.len() + footer.len() + gaps * 2);
    let rows = lines.len().min(body_room);
    let height = (head.len() + footer.len() + gaps * 2 + rows + 2).min(usize::from(area.height));
    let rect = Rect { height: u16::try_from(height).unwrap_or(area.height), ..area };
    // More requests queued behind this one: say so, so a repeated key is not mistaken for answering the same one.
    let mut block = modal_block(" Approval needed ");
    if waiting > 0 {
        block = block.title(Span::styled(format!(" {waiting} more waiting "), Style::default().fg(Color::Yellow)));
    }
    let inner = block.inner(rect);
    frame.render_widget(Clear, rect);
    frame.render_widget(block, rect);
    let head_rows = u16::try_from(head.len()).unwrap_or(0).min(inner.height);
    let footer_rows = u16::try_from(footer.len()).unwrap_or(0).min(inner.height.saturating_sub(head_rows));
    let gap = u16::try_from(gaps).unwrap_or(0);
    let body = Rect {
        y: inner.y + head_rows + gap,
        height: inner.height.saturating_sub(head_rows + footer_rows + gap * 2),
        ..inner
    };
    // Text that does not fit keeps its last body row for the fold marker, so the marker never takes a row of the text
    // and `limit` (what must be scrolled through before approving) counts only rows that can be seen.
    let folded = lines.len() > usize::from(body.height);
    let viewport = usize::from(body.height).saturating_sub(usize::from(folded));
    let limit = lines.len().saturating_sub(viewport);
    // Shown means: the heading, the decisions and at least one row of the change (when there is one) are on screen.
    let drawn = usize::from(head_rows) == head.len() && footer_rows >= 1 && (lines.is_empty() || viewport >= 1);
    if !drawn && footer_rows >= 1 {
        // Not enough room to show the change: say so where the decisions are, and decide nothing until it fits.
        let last = footer.len() - 1;
        footer[last] = Line::from(Span::styled("enlarge the terminal to see the proposed change", Style::default().fg(Color::Yellow)));
    }
    let top = approval.scroll.min(limit);
    let total = lines.len();
    let mut shown: Vec<Line> = lines.into_iter().skip(top).take(viewport).collect();
    if folded && viewport >= 1 {
        let below = limit - top;
        let marker = match (below, width) {
            (0, _) => "end of change · ↑ scrolls back".to_string(),
            (_, ..44) => format!("↓ {below} more · ↓ reads on"),
            (_, 44..) => format!("↓ {below} more rows below · ↓ reads on"),
        };
        shown.push(Line::from(Span::styled(marker, Style::default().fg(Color::Yellow))));
    }
    frame.render_widget(Paragraph::new(head), Rect { height: head_rows, ..inner });
    frame.render_widget(Paragraph::new(shown), body);
    frame.render_widget(Paragraph::new(footer), Rect { y: inner.y + inner.height - footer_rows, height: footer_rows, ..inner });
    layout.overlay_rows = viewport;
    layout.overlay_limit = limit;
    layout.approval_drawn = drawn;
    layout.approval_total = total;
    layout.approval_top = top;
    layout.approval_seen_to = (top + viewport).min(total);
    layout.approval_width = width;
}

fn line_style(kind: LineKind) -> Style {
    match kind {
        LineKind::Added => Style::default().fg(Color::Green),
        LineKind::Removed => Style::default().fg(Color::Red),
        LineKind::Hunk => Style::default().fg(Color::Cyan),
        LineKind::Meta => Style::default().fg(MUTED),
        LineKind::Command => Style::default()
            .fg(Color::White)
            .add_modifier(Modifier::BOLD),
        LineKind::Context => Style::default().fg(Color::White),
    }
}

/// How a row of a command's `diff` output is coloured: rows that are not part of a hunk read as headers.
fn diff_row_kind(row: &str) -> LineKind {
    if row.starts_with('+') && !row.starts_with("+++") {
        LineKind::Added
    } else if row.starts_with('-') && !row.starts_with("---") {
        LineKind::Removed
    } else if row.starts_with("@@") {
        LineKind::Hunk
    } else if row.starts_with(' ') {
        LineKind::Context
    } else {
        LineKind::Meta

    }

    /// Tests that drive keys without drawing: the panel is shown and its change counts as read, as a frame that drew
    /// all of it would leave it.
    #[cfg(test)]
    pub fn note_approval_shown_and_read(&mut self, now: Instant) {
        self.note_approval_shown(now);
        if let Some(Overlay::Approval(approval)) = &mut self.overlay {
            approval.read_all = true;
        }
    }

    /// The approval panel is on screen now: its guard (when typing was in flight) counts from here, not from when the
    /// request arrived.
    pub fn note_approval_shown(&mut self, now: Instant) {
        let in_flight = self.last_key.is_some_and(|at| now.saturating_duration_since(at) < APPROVAL_IN_FLIGHT);
        if let Some(Overlay::Approval(approval)) = &mut self.overlay
            && !approval.shown
        {
            approval.shown = true;
            // A key held down when the panel opened (the Enter that sent the prompt) starts auto-repeating after a
            // delay (660 ms by default on X11, longer with some accessibility settings): decision keys stay inert until that key
            // has been quiet for `APPROVAL_REPEAT_QUIET` (1 s).
            let quiet = self.last_key.map_or(now, |at| at + APPROVAL_REPEAT_QUIET);
            approval.guard_until = in_flight.then(|| (now + APPROVAL_GUARD).max(quiet));
        }
    }

    /// Records what the frame measured and clamps scrolling to it.
    pub fn note_layout(&mut self, layout: LiveLayout) {
        // Shown only when the frame drew the panel with its change visible (not on a too-small screen).
        if layout.approval_drawn {
            self.note_approval_shown(Instant::now());
        } else if let Some(Overlay::Approval(approval)) = &mut self.overlay {
            // Not on screen this frame (too small a terminal): no decision until it is drawn again, timed afresh.
            approval.shown = false;
        }
        if let Some(back) = layout.followed {
            self.scroll_back = back;
            self.follow = false;
        }
        if let Some(back) = layout.anchored {
            self.scroll_back = back;
        }
        self.scroll_back = self.scroll_back.min(layout.scroll_limit);
        self.anchor = if self.scroll_back > 0 { layout.top } else { None };
        if self.scroll_back == 0 {
            self.unseen = false;
        }
        if let Some(Overlay::Review(review)) = &mut self.overlay {
            review.top = review.top.min(layout.overlay_limit);
            review.left = review.left.min(layout.overlay_hlimit);
        }
        if let Some(
            Overlay::Approval(Approval { scroll, .. })
            | Overlay::Help { scroll }
            | Overlay::Paste { scroll, .. }
            | Overlay::Detail(Detail { scroll, .. })
            | Overlay::Receipt(ReceiptPanel { scroll, .. }),
        ) = &mut self.overlay
        {
            *scroll = (*scroll).min(layout.overlay_limit);
        }
        if let Some(Overlay::Approval(approval)) = &mut self.overlay {
            // What counts as read is what a frame drew, from the top without a gap (see `seen_through`).
            if approval.seen_width != layout.approval_width {
                approval.seen_width = layout.approval_width;
                approval.seen_through = 0;
            }
            if layout.approval_drawn && layout.approval_top <= approval.seen_through {
                approval.seen_through = approval.seen_through.max(layout.approval_seen_to);
            }
            approval.read_all = layout.approval_drawn && approval.seen_through >= layout.approval_total;
            // The refusal told the operator to scroll to the end: once they have, it no longer applies.
            if approval.read_all && approval.notice == Some(APPROVAL_UNSEEN) {
                approval.notice = None;
            }
        }
        self.layout = layout;
    }

