    /// Keys that reached the screen together, applied one at a time in the order they were typed. At an open approval
    /// more than one press at once is typing (or a paste without bracketed paste), so the decision keys are inert for
    /// the batch (the panel's guard, as for input typed before the panel appeared): `y`, `n`, `a` become text of the
    /// draft and Enter does nothing. Every other key (text, Backspace, arrows, Tab, Esc) acts exactly as it does alone.
/// One display cell group: a grapheme (or a visible stand-in for a control character) and its column width.
#[derive(Clone, Debug, PartialEq)]
struct Cell {
    text: String,
    width: usize,
    /// `None` paints as metadata (the clip markers).
    token: Option<Token>,
}

/// The visible stand-in for a character a terminal would interpret: control pictures for C0 controls (`␛` for ESC),
/// `␡` for DEL, `<U+XXXX>` for C1 controls and bidirectional overrides. `None` for ordinary characters.
pub fn visible_control(c: char) -> Option<String> {
    let code = c as u32;
    match code {
        0x00..=0x1f => char::from_u32(0x2400 + code).map(String::from),
        0x7f => Some("␡".to_string()),
        0x80..=0x9f | 0x61c | 0x200e | 0x200f | 0x202a..=0x202e | 0x2066..=0x2069 => Some(format!("<U+{code:04X}>")),
        _ => None,
    }
}

/// Approval rows only: everything `visible_control` shows, plus the characters that draw as nothing or as a blank
/// (zero-width, no-break and other space characters, soft hyphen, variation selectors, tag characters, line and
/// paragraph separators, braille blank). Ordinary prose never goes through this, so emoji and CJK text are unaffected.
pub fn approval_visible_control(c: char) -> Option<String> {
    visible_control(c).or_else(|| {
        let code = c as u32;
        match code {
            0xa0 | 0xad | 0x34f | 0x115f | 0x1160 | 0x1680 | 0x17b4..=0x17b5 | 0x180b..=0x180f | 0x2000..=0x200d | 0x2028..=0x202f | 0x205f..=0x206f | 0x2800 | 0x3000
            | 0x3164 | 0xfe00..=0xfe0f | 0xfeff | 0xffa0 | 0xfff0..=0xfffb | 0xe0000..=0xe0fff => Some(format!("<U+{code:04X}>")),
            _ => None,
        }
    })
}

/// `safe_text` for approval rows, with the wider `approval_visible_control` set.
pub fn approval_safe_text(text: &str) -> String {
    text.chars().map(|c| approval_visible_control(c).unwrap_or_else(|| c.to_string())).collect()
}

/// Text safe to draw: every control character replaced by its visible stand-in (tabs and newlines included).
pub fn safe_text(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match visible_control(c) {
            Some(stand_in) => out.push_str(&stand_in),
            None => out.push(c),
        }
    }
    out
}

fn cells(text: &str, lang: Option<&Lang>) -> Vec<Cell> {
    let tokens = lang.map(|lang| highlight::highlight(lang, text)).unwrap_or_default();
    let mut token_at = tokens.iter().peekable();
    let mut out: Vec<Cell> = Vec::new();
    let mut col = 0;
    for (offset, grapheme) in text.grapheme_indices(true) {
        while token_at.peek().is_some_and(|(_, end, _)| *end <= offset) {
            token_at.next();
        }
        let token = token_at.peek().map_or(Token::Plain, |(_, _, t)| *t);
        if grapheme == "\t" {
            let spaces = TAB - col % TAB;
            for _ in 0..spaces {
                out.push(Cell { text: " ".into(), width: 1, token: Some(token) });
            }
            col += spaces;
            continue;
        }
        if grapheme.chars().any(|c| visible_control(c).is_some()) {
            for c in grapheme.chars() {
                let shown = visible_control(c).unwrap_or_else(|| c.to_string());
                for piece in shown.chars() {
                    let width = UnicodeWidthStr::width(piece.to_string().as_str()).max(1);
                    out.push(Cell { text: piece.to_string(), width, token: Some(token) });
                    col += width;
                }
            }
            continue;
        }
        let width = UnicodeWidthStr::width(grapheme);
        if width == 0 {
            match out.last_mut() {
                Some(previous) => previous.text.push_str(grapheme),
                None => out.push(Cell { text: grapheme.to_string(), width: 0, token: Some(token) }),
            }
            continue;
        }
        out.push(Cell { text: grapheme.to_string(), width, token: Some(token) });
        col += width;
    }
    out
}

/// Display width of a diff line's content (tabs expanded, controls made visible).
pub fn content_width(text: &str) -> usize {
    cells(text, None).iter().map(|c| c.width).sum()
}

fn spaces(n: usize) -> Cell {
    Cell { text: " ".repeat(n), width: n, token: Some(Token::Plain) }
}

/// Splits content cells into rows of at most `width` columns. Wrapping breaks after a space when one falls in the
/// latter two thirds of the row (the space stays at the row's end, so no character is lost), else at the edge.
fn fit_rows(cells: Vec<Cell>, width: usize, fit: Fit) -> Vec<Vec<Cell>> {
    match fit {
        Fit::Wrap => {
            let mut rows: Vec<Vec<Cell>> = vec![Vec::new()];
            let mut used = 0;
            for cell in cells {
                if used + cell.width > width && used > 0 {
                    let row = rows.last_mut().expect("a row is open");
                    let mut carried = Vec::new();
                    if cell.text != " " {
                        let mut at = 0;
                        let mut space = None;
                        for (index, c) in row.iter().enumerate() {
                            at += c.width;
                            if c.text == " " && at * 3 > width {
                                space = Some(index);
                            }
                        }
                        if let Some(index) = space {
                            carried = row.split_off(index + 1);
    }
    let inner = block.inner(rows[2]);
    frame.render_widget(block, rows[2]);
    render_composer(frame, inner, state, &composer);
    if let Some((found, pick)) = state.completion() {
        render_completion(frame, rows[1], &found, pick);
    }
    if state.overlay.is_some() {
        // A panel takes the transcript area: nothing half-covered shows beside it.
        frame.render_widget(Clear, rows[1]);
    }
    match &state.overlay {
        Some(Overlay::Approval(approval)) => {
            render_approval(frame, rows[1], approval, state.depth, state.approvals_waiting(), &mut layout);
        }
        Some(Overlay::CheckpointChoice { message, selected, .. }) => {
            layout.overlay_rows = render_checkpoint_choice(frame, rows[1], message, *selected);
        }
        Some(Overlay::Help { scroll }) => {
            (layout.overlay_rows, layout.overlay_limit) =
                render_help(frame, rows[1], *scroll, &state.commands);
    Context,
    Command,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ReviewLine {
    pub kind: LineKind,
    pub text: String,
}

fn line(kind: LineKind, text: impl Into<String>) -> ReviewLine {
    ReviewLine {
        kind,
        text: text.into(),
    }
}

/// A row of a command or script as drawn: tabs as spaces, every other control character (a lone carriage return that
/// would redraw the line, ESC) and bidirectional override shown as a visible stand-in, so what is displayed is what runs.
fn safe_row(row: &str) -> String {
    crate::diff_view::approval_safe_text(&row.replace('\t', "    "))
}

fn truncation_note() -> ReviewLine {
    line(
        LineKind::Meta,
        "… preview truncated; the action uses the full content",
    )
}

/// The rows the approval panel draws for a review. Every row passes through `safe_row` here, whatever its kind or
/// field (a path, a hunk, a command, an argument), so no review text can reach the screen as a control character or an
/// invisible one.
pub fn review_lines(review: &Review) -> Vec<ReviewLine> {
    let mut lines = review_rows(review);
    for row in &mut lines {
        row.text = safe_row(&row.text);
    }
    lines
}

